import{z as B,x as d,o as E,c as A,q as t,j as s,D as e,d as n,s as l,S as i,b as o}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"CSPRNG","description":"","frontmatter":{"title":"CSPRNG","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/csprng.md","filePath":"cs/csprng.md","lastUpdated":1791413859000}'),p={name:"cs/csprng.md"};function c(D,a,h,P,S,C){const r=d("Mermaid");return E(),A("div",null,[a[2]||(a[2]=t('<h1 id="csprng" tabindex="-1">CSPRNG <a class="header-anchor" href="#csprng" aria-label="Permalink to &quot;CSPRNG&quot;">​</a></h1><div class="epigraph"><p>密码学伪随机不是 `rand()`：要前向保密式的状态演化、要抗回溯、熵源要估价。nonce、OAEP 种子、ECDSA 的 $k$、密钥本身，都从这里出来。</p><footer>—— NIST SP 800-90A；对照 Ferguson, Schneier and Kohno 对生成器失败；Katz and Lindell 的 PRG 合同</footer></div><p>上一课<a href="/cs/ecdsa-eddsa">ECDSA / EdDSA</a>把确定性签名当成对 RNG 失败的修复。缺口是<strong>其余一切仍要生成器</strong>：密钥、nonce、盐。PRG 课给了理论 \\(G(s)\\)；本课给操作系统与协议里的 CSPRNG 合同。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>理论 PRG 假设种子均匀保密。实践：熵从中断、抖动、硬件指令来，估计不足会出弱密钥。生成器状态泄漏后，若不能前向安全演化，过去输出可被回溯。缺口是 CSPRNG 的再播种与预测抗性，不是再定义不可区分游戏。</p><p><span class="marginnote">熵在这里就是&quot;不可预测的意外程度&quot;的计量：中断到达的时刻、磁盘寻道抖动你猜不准，才算熵；时间戳一猜就中，一点熵都没有——拿哈希搅一遍也不会变多。</span></p><h3 id="不要用哈希时间戳当密钥" tabindex="-1">不要用哈希时间戳当密钥 <a class="header-anchor" href="#不要用哈希时间戳当密钥" aria-label="Permalink to &quot;不要用哈希时间戳当密钥&quot;">​</a></h3><p>可预测输入不是熵。Debian OpenSSL 一类事故是种子空间塌缩——点名失败模式，不给复现。</p><p><span class="marginnote">初学者容易以为&quot;哈希过就随机了&quot;。哈希只把输入搅混，不新增不可预测性：可预测的输入哈希完仍可预测。Debian 事故正是种子来源被削到只剩极少几种可能，输出看似随机、实则枚举得出来。</span></p><p><span class="marginnote">SP 800-90A 的 Hash_DRBG / HMAC_DRBG / CTR_DRBG。Linux getrandom / 用户态 ChaCha。Fork 后要重种。本课不写如何削弱某生成器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分层：硬件熵 → 内核混合池 → 用户态 DRBG。列出消费者：密钥、nonce、盐、OAEP 种子。Ed25519 仍依赖 CSPRNG 生成私钥本身。</p>',13)),(E(),s(i,null,{default:e(()=>[l(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENT%5B%22%E7%86%B5%E6%BA%90%22%5D%20--%3E%20POOL%5B%22%E6%B7%B7%E5%90%88%E6%B1%A0%22%5D%0A%20%20POOL%20--%3E%20DRBG%5B%22CSPRNG%20%E7%8A%B6%E6%80%81%22%5D%0A%20%20DRBG%20--%3E%20OUT%5B%22%E5%AF%86%E9%92%A5%20%2F%20nonce%20%2F%20%E7%9B%90%22%5D%0A%20%20DRBG%20--%3E%20FS%5B%22%E5%89%8D%E5%90%91%E6%BC%94%E5%8C%96%E9%98%B2%E5%9B%9E%E6%BA%AF%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[n("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"计算安全处处假设「随机带」。CSPRNG 是这条带的工程实现。失败表现为可预测 nonce（回到误用课）或可预测 \\(k\\)（回到 ECDSA）。HKDF 下一课是从已有秘密派生，不是从熵池抽——二者分工。",-1)),(E(),s(i,null,{default:e(()=>[l(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%BD%93%E5%89%8D%E5%86%85%E9%83%A8%E7%8A%B6%E6%80%81%22%5D%20--%3E%20G%5B%22%E7%94%9F%E6%88%90%E8%BE%93%E5%87%BA%E5%9D%97%22%5D%0A%20%20G%20--%3E%20UP%5B%22%E7%8A%B6%E6%80%81%E5%8D%95%E5%90%91%E6%BC%94%E5%8C%96%EF%BC%8C%E8%A6%86%E7%9B%96%E6%97%A7%E7%8A%B6%E6%80%81%22%5D%0A%20%20UP%20--%3E%20N%5B%22%E4%B8%8B%E4%B8%80%E5%9D%97%E8%BE%93%E5%87%BA%22%5D%0A%20%20N%20--%3E%20G%0A%20%20RS%5B%22%E5%86%8D%E6%92%AD%E7%A7%8D%EF%BC%9A%E6%8E%BA%E5%85%A5%E6%96%B0%E7%86%B5%22%5D%20--%3E%20UP%0A%20%20LK%5B%22%E6%94%BB%E5%87%BB%E8%80%85%E6%8B%BF%E5%88%B0%E7%8E%B0%E7%8A%B6%E6%80%81%22%5D%20--%3E%7C%22%E8%83%BD%E7%AE%97%22%7C%20FUT%5B%22%E4%B9%8B%E5%90%8E%E7%9A%84%E8%BE%93%E5%87%BA%22%5D%0A%20%20LK%20-.-%3E%7C%22%E5%89%8D%E5%90%91%E5%AE%89%E5%85%A8%E4%B8%8B%E7%AE%97%E4%B8%8D%E5%87%BA%22%7C%20PAST%5B%22%E4%B9%8B%E5%89%8D%E7%9A%84%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">普通 <code>rand()</code> 的目标是统计上看着均匀、跑得快，读过源码就能预测全部后续输出；CSPRNG 的目标是&quot;读了源码也猜不出&quot;，秘密全在单向演化的状态里。两个名字都带&quot;随机&quot;，合同天差地别。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不评估具体 CPU 指令的熵质量论文全文。下一课 HKDF：已有 IKM 时如何拉出多把键，而不是再去碰熵池。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>签名确定性不取消密钥生成对 CSPRNG 的需求。</li><li>要抗预测与回溯；熵估计失败是规格事故。</li><li><code>rand()</code> 与时间戳不是 CSPRNG。</li><li>下一课 HKDF：从已有秘密派生键。</li><li>出处：NIST SP 800-90A；Ferguson, Schneier and Kohno；对照 RFC 4086。</li></ul>',5))])}const _=B(p,[["render",c]]);export{m as __pageData,_ as default};
